<template>
  <BrokerStyles />
      <section data-broker-scope class="scroll loaners" v-bng-ui-nav-scroll>
        <div data-broker-scope class="view-bar"><div data-broker-scope class="depot-strip"><strong data-broker-scope>{{ s.data.depot?.name || 'Find a facility with loaner bays' }}</strong><button data-broker-scope class="text-btn" :disabled="!s.data.depot" @click="s.action('navigateDepot')">Navigate →</button></div><BrokerExpand v-if="!s.expanded" /></div>
        <template v-if="s.data.rentals.length"><h3 data-broker-scope>Your equipment</h3><div data-broker-scope class="loaner-list"><article data-broker-scope v-for="r in s.data.rentals" :key="r.id" class="loaner-card"><div data-broker-scope v-if="r.preview" class="loaner-img"><img data-broker-scope :src="r.preview" alt="" loading="lazy" /></div><div data-broker-scope class="card-top"><strong data-broker-scope>{{ r.name }}</strong><span data-broker-scope class="pay"><MoneyAmount data-broker-scope>{{ rate(r.rate) }}</MoneyAmount>/hr</span></div><p data-broker-scope class="card-line"><span data-broker-scope class="pill" :class="r.status === 'reserved' ? 'accent' : 'ok'">{{ r.status === 'reserved' ? 'Reserved' : 'Rented' }}</span>{{ [r.status === 'reserved' ? 'Rate locked' : 'Billed while out', r.status === 'rented' && r.vehicleSpawned === false ? 'Stored off map' : ''].filter(Boolean).join(' · ') }}</p><div data-broker-scope class="rental-actions"><button data-broker-scope v-if="r.status === 'reserved'" :disabled="working" @click="s.action('cancelRental', { id: r.id })">Cancel</button><button data-broker-scope v-if="r.status === 'rented'" :disabled="working" @click="s.action('navigateRental', { id: r.id })">Locate vehicle</button><button data-broker-scope v-if="r.status === 'reserved'" class="primary" :disabled="working || !(r.atPickup || s.data.depot?.atDepot)" @click="s.action('collectRental', { id: r.id })">Collect</button><button data-broker-scope v-if="r.status === 'rented'" class="primary" :disabled="working || !(r.atPickup || s.data.depot?.atDepot)" @click="s.action('returnRental', { id: r.id })">Return empty</button></div></article></div></template>
        <p data-broker-scope class="muted">Rent, collect and return at any facility with loaner bays.</p>
        <div data-broker-scope class="jobs-tabs" role="tablist" aria-label="Equipment availability"><button data-broker-scope data-fk="available-loaners" role="tab" :aria-selected="s.availability === 'available'" :class="{ active: s.availability === 'available' }" @click="s.availability = 'available'">Available</button><button data-broker-scope data-fk="locked-loaners" role="tab" :aria-selected="s.availability === 'locked'" :class="{ active: s.availability === 'locked' }" @click="s.availability = 'locked'">Locked</button></div>
        <h3 data-broker-scope>{{ s.availability === 'locked' ? 'Locked equipment' : 'Available equipment' }}</h3><div data-broker-scope class="loaner-list"><article data-broker-scope v-for="r in loanerRows" :key="r.id" class="loaner-card" :class="{ 'at-pickup': r.atPickup && !isLocked(r) }"><div data-broker-scope v-if="r.preview" class="loaner-img"><img data-broker-scope :src="r.preview" alt="" loading="lazy" /></div><div data-broker-scope class="card-top"><strong data-broker-scope>{{ r.name }}</strong><span data-broker-scope class="pay"><MoneyAmount data-broker-scope>{{ rate(r.rate) }}</MoneyAmount>/hr</span></div><p data-broker-scope class="card-line card-facts"><span data-broker-scope v-if="loanerMarket(r)" class="card-fact"><span data-broker-scope class="card-fact-key">Market</span>{{ loanerMarket(r) }}</span><span data-broker-scope v-if="capacityText(r)" class="card-fact"><span data-broker-scope class="card-fact-key">Capacity</span>{{ capacityText(r) }}</span><span data-broker-scope v-if="!r.basic" class="pill">Visiting stock</span></p><BrokerAccess data-broker-scope :row="r" compact /><div data-broker-scope class="rental-actions"><button data-broker-scope class="text-btn" @click="s.chooseMarket(r.market)">Explore work</button><button data-broker-scope :data-fk="'reserve:' + r.id" :aria-disabled="!!working || isLocked(r) || !s.data.depot" @click="!working && !isLocked(r) && s.data.depot && s.action('reserveRental', { id: r.id })">Reserve</button><button data-broker-scope v-if="r.atPickup && !isLocked(r)" class="primary" :data-fk="'start:' + r.id" :aria-busy="!!working" @click="startHere(r)">Rent and collect now</button></div></article></div>
        <p data-broker-scope class="muted">Rates are per hour of unpaused simulation time, not the dashboard clock. Quotes lock when booked. Billing runs from collection to return, including parked time.</p>
      </section>
</template>

<script setup>
import { vBngUiNavScroll } from "@/common/directives"
import BrokerStyles from './BrokerStyles.vue'
import MoneyAmount from '../../../components/MoneyAmount.vue'
import BrokerAccess from './BrokerAccess.vue'
import BrokerExpand from './BrokerExpand.vue'
import { computed, inject } from 'vue'
const { startHere, isLocked, markets, s, working, rate, capacityText } = inject(Symbol.for('overhaul.phoneBroker'))
const loanerMarket = r => markets.value.find(m => m.id === r.market)?.name
const loanerRows = computed(() => s.data.loaners.filter(row => isLocked(row) === (s.availability === 'locked')).sort((a, b) => Number(!!b.atPickup) - Number(!!a.atPickup)))
</script>
